# examine 8-shape and zero density per region
zs = (g==0)
print("zero count:", zs.sum(), "8 count:", (g==8).sum())
# connected components of zeros (4-conn)
from collections import deque
seen=np.zeros_like(zs,bool); comps=[]
H,W=zs.shape
for r in range(H):
    for c in range(W):
        if zs[r,c] and not seen[r,c]:
            q=deque([(r,c)]); seen[r,c]=1; comp=[]
            while q:
                a,b=q.popleft(); comp.append((a,b))
                for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                    x,y=a+da,b+db
                    if 0<=x<H and 0<=y<W and zs[x,y] and not seen[x,y]:
                        seen[x,y]=1; q.append((x,y))
            comps.append(comp)
comps.sort(key=len, reverse=True)
print([len(c) for c in comps])
for c in comps[:6]:
    rs=[p[0] for p in c]; cs=[p[1] for p in c]
    print(len(c), min(rs),max(rs),min(cs),max(cs))
